import{_ as e,o as t,c as l,O as i}from"./chunks/framework.ac0f74f3.js";const r="/assets/ygxx.4431cc71.png",o="/assets/ygxx1.511a6a97.png",m=JSON.parse('{"title":"员工权限","description":"","frontmatter":{},"headers":[],"relativePath":"基础设置/基础设置/员工权限.md","filePath":"基础设置/基础设置/员工权限.md"}'),p={name:"基础设置/基础设置/员工权限.md"};function s(n,a,c,h,d,u){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="员工权限" tabindex="-1">员工权限 <a class="header-anchor" href="#员工权限" aria-label="Permalink to &quot;员工权限&quot;">​</a></h1><blockquote><p>员工权限是管理信息系统或人事管理系统中的一个关键组成部分，它主要负责存储、管理和维护员工的基本信息，以及提供相关的数据支持和查询功能，（以基础设置-员工信息数据为准，同步至员工档案）</p><p>高级管理员可配置所有员工权限，普通管理员可配置，普通员工，运营管理员</p></blockquote><h4 id="_1-新增人员" tabindex="-1">1. 新增人员 <a class="header-anchor" href="#_1-新增人员" aria-label="Permalink to &quot;1. 新增人员&quot;">​</a></h4><ul><li><p>点击添加人员图标，可新增人员信息的工号，姓名，电话，岗位</p></li><li><p>新增员工时，如果员工档案中不存在此人的人员信息，人员信息同步至员工档案（姓名，手机号，岗位，启停状态[在职/离职]）</p></li><li><p>新增员工时，如果员工档案中存在此人员信息，当人员信息进行了修改（姓名或电话与员工档案中记录数据至少有一个信息不同），更新人员信息至员工档案（姓名、手机号、岗位、工作上级）</p></li></ul><h4 id="_2-是否启用" tabindex="-1">2.是否启用 <a class="header-anchor" href="#_2-是否启用" aria-label="Permalink to &quot;2.是否启用&quot;">​</a></h4><ul><li><p>启用的情况下这个员工可登录系统，不启用的情况下员工无法登录账号</p></li><li><p>在停用的情况下是不可以编辑员工信息的，停用时系统内不显该员工的信息资料</p></li><li><p>修改员工启停状态时，也将状态同步至员工档案表中的在职离职字段，其他界面涉及员工信息弹窗会显示离职状态</p></li></ul><h4 id="_3-批量导入" tabindex="-1">3.批量导入 <a class="header-anchor" href="#_3-批量导入" aria-label="Permalink to &quot;3.批量导入&quot;">​</a></h4><ul><li>点击批量导入，下载模板，编辑模板后上传即可</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_4-编辑" tabindex="-1">4.编辑 <a class="header-anchor" href="#_4-编辑" aria-label="Permalink to &quot;4.编辑&quot;">​</a></h4><ul><li>点击编辑可更改员工的工号，姓名、电话、岗位、工作上级、权限等级，提交后同步至员工档案（工号，姓名，电话，岗位，工作上级）</li></ul><h4 id="_5-导出" tabindex="-1">5.导出 <a class="header-anchor" href="#_5-导出" aria-label="Permalink to &quot;5.导出&quot;">​</a></h4><p>-点击导出按钮</p><p>-勾选需要导出的信息</p><p>-也可手动输入需导出N条信息进行导出</p><p>-再次点击导出按钮导出</p><p><img src="'+o+'" alt="如图所示"></p>',17)])])}const b=e(p,[["render",s]]);export{m as __pageData,b as default};
